 static bool Until(Func<bool> f,int ms=5000){var until=DateTime.UtcNow.AddMilliseconds(ms);while(!f()&&DateTime.UtcNow<until)Pump(5);return f();}
 static Label Hint(WbTasksForm f){return (Label)Field(f,"hint");}static DataGridView Grid(WbTasksForm f){return (DataGridView)Field(f,"grid");}static bool Busy(WbTasksForm f){return (bool)Field(f,"operating");}static Button Button(WbTasksForm f,string t){return All(f).OfType<Button>().Single(b=>b.Text==t);}
 static bool Inside(Control c){if(!c.Visible)return false;var r=c.RectangleToScreen(c.ClientRectangle);for(var p=c.Parent;p!=null;p=p.Parent)if(!p.RectangleToScreen(p.ClientRectangle).Contains(r))return false;return true;}
 static Dictionary<string,object> Tasks(int progress=0,bool global=false){return Json.Object(Json.Text(new {checkedAt="2026-10-16T13:30:00+08:00",tasks=Enumerable.Range(1,12).Select(i=>new {accountId=global?(i>6?"SAMPLE-WB-B":"SAMPLE-WB-A"):"SAMPLE-WB-A",taskCode="SAMPLE_TASK_"+(global?(i-1)%6+1:i),title="SAMPLE 自动任务 "+i,description="逐项执行、确认与回执保留。",automaticExecution=i%2==1,accepted=progress>0,current=progress,target=3,rewardCredit=100,acceptStatus=progress>0?"accepted":"not_accepted"}).ToArray(),receipts=new[]{new{accountId="SAMPLE-WB-A",taskCode="SAMPLE_TASK_1",status="accepted",serverConfirmed=true}}}));}
 sealed class Handler:HttpMessageHandler {
  internal int submits,lookups,polls,cancels,legacyReads;internal bool loseAck,failStart,failPollOnce,holdStart,holdPoll,fastComplete,cancelComplete,holdCancel,global,terminalFailure,timeout,missing,finish;internal Dictionary<string,object> job;internal Dictionary<string,object> submitted;internal TaskCompletionSource<HttpResponseMessage> pendingCancel;internal int cancelledReads;internal DateTime began=DateTime.UtcNow;
