  protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){string path=request.RequestUri.AbsolutePath;
   if(request.Method==HttpMethod.Post&&path=="/admin/workbuddy/task-jobs"){submits++;submitted=Json.Object(await request.Content.ReadAsStringAsync());if(failStart)return Response(new{error=new{message="SAMPLE_START_FAILED"}},HttpStatusCode.ServiceUnavailable);NewJob(Json.Get(submitted,"action"));if(holdStart){await Task.Delay(Timeout.Infinite,token);}if(loseAck)throw new HttpRequestException("SAMPLE_LOST_ACK");return Response(job,HttpStatusCode.Accepted);}
   if(request.Method==HttpMethod.Post&&path.EndsWith("/cancel")){cancels++;job["status"]="cancelling";if(holdCancel){pendingCancel=new TaskCompletionSource<HttpResponseMessage>();return await pendingCancel.Task;}return Response(job);}
   if(request.Method==HttpMethod.Get&&path=="/admin/workbuddy/task-jobs"){lookups++;return Response(new{job=job!=null&&new[]{"running","cancelling"}.Contains(Json.Get(job,"status"))?job:null});}
   if(request.Method==HttpMethod.Get&&path=="/admin/workbuddy/tasks"){legacyReads++;return Response(Tasks());}
   if(request.Method==HttpMethod.Get){polls++;if(failPollOnce){failPollOnce=false;throw new HttpRequestException("SAMPLE_CONNECTION_LOST");}if(holdPoll){try{await Task.Delay(Timeout.Infinite,token);}catch(OperationCanceledException){cancelledReads++;throw;}}if(missing)return Response(new{error=new{message="SAMPLE_JOB_MISSING"}},HttpStatusCode.NotFound);
    job["progress"]=new Dictionary<string,object>{{"phase",Json.Get(job,"status")=="cancelling"?"waiting_confirmation":"progress_poll"},{"taskCode","SAMPLE_TASK_2"},{"accountId","SAMPLE-WB-A"},{"completed",Math.Min(11,polls)},{"total",12},{"elapsedMs",(int)(DateTime.UtcNow-began).TotalMilliseconds}};job["snapshot"]=Tasks(1,global);
